// Package appctx defines a structured wrapper around context.WithValue
package appctx

import (
	"context"
	"strconv"

	"github.com/github/go-stats/ps"

	"github.com/github/go-exceptions"

	"github.com/github/turboscan/ts/o11y"

	throttler "github.com/github/go-freno-client"

	"github.com/github/turboscan/ts/config"

	"github.com/github/github-telemetry-go/kvp"
	"github.com/github/github-telemetry-go/log"
	"github.com/github/go-http/v2/middleware/tenant"
	"github.com/github/go-stats"

	"github.com/github/turboscan/ts"
)

type contextValueKey int

const (
	aqueductJobRetryCountKey contextValueKey = iota
	loggerKey
	gormbulkKey
	statsKey
	throttlerKey
	reporterKey
)

func With(ctx context.Context, fields ...kvp.Field) context.Context {
	return WithLogger(ctx, Logger(ctx).WithFields(fields...))
}

func WithKVPs(ctx context.Context, o ...KVPer) context.Context {
	kvps := make([]kvp.Field, 0, len(o))
	for _, v := range o {
		kvps = append(kvps, v.AsKVP())
	}
	return With(ctx, kvps...)
}

type KVPer interface {
	AsKVP() kvp.Field
}

// WithRequestID returns a modified version of the provided context, attaching the provided request ID.
func WithRequestID(ctx context.Context, requestID string) context.Context {
	return With(ctx, kvp.String("gh.request_id", requestID))
}

// WithRepositoryID returns a modified version of the provided context, attaching the provided repository ID.
func WithRepositoryID(ctx context.Context, repositoryID uint64) context.Context {
	return With(ctx, ts.RepositoryEID(repositoryID).AsKVP())
}

// WithHydroMessage returns a modified version of the provided context,
// attaching the provided topic, partition and offset.
//
// Design note: This is not actually application-specific like other fields in
// this package. If analysis.hydro.go were to be autogenerated at some point, it
// would make sense for this method to be part of a supporting library, much
// like results.twirp.go contains calls like
// 'ctxsetters.WithMethodName(ctx, "GetAnalysis")'.
//
// [Log KVPs] Surprisingly, searching the OTel semantic conventions for Hydro
// doesn't reveal anything as of 2022-09-26. So, let's make these Turboscan-specific
// for now, in the hope that Hydro will add some conventions later down the line.
func WithHydroMessage(ctx context.Context, hydroTopic string, hydroPartition int32, hydroOffset int64) context.Context {
	ctx = With(ctx, kvp.String("gh.hydro.msg.topic", hydroTopic))
	ctx = With(ctx, kvp.Int64("gh.hydro.msg.offset", hydroOffset))
	return With(ctx, kvp.Int("gh.hydro.msg.partition", int(hydroPartition)))
}

// WithTenant returns a modified version of the provided context, attaching the provided tenant.
func WithTenant(ctx context.Context, t *ts.ProximaTenant) context.Context {
	ctx = tenant.TenantContext(ctx, t.Slug)
	ctx = tenant.TenantIDContext(ctx, strconv.Itoa(int((t.ID))))
	return ctx
}

func ContextError(ctx context.Context, method string) error {
	if err := ctx.Err(); err != nil {
		Logger(ctx).WithFields(kvp.String("gh.turboscan.method", method)).WithError(err).Info("Context has errored")
		Stats(ctx).Counter("context_error", stats.Tags{"method": method}, 1)
		return err
	}
	return nil
}

func WithAqueductJobRetryCount(ctx context.Context, retryCount uint8) context.Context {
	return context.WithValue(ctx, aqueductJobRetryCountKey, retryCount)
}

func GetAqueductJobRetryCount(ctx context.Context) uint8 {
	if retryCount, ok := ctx.Value(aqueductJobRetryCountKey).(uint8); ok {
		return retryCount
	}
	return 0
}

func Throttler(ctx context.Context) throttler.Throttler {
	if v, ok := ctx.Value(throttlerKey).(throttler.Throttler); ok {
		return v
	}
	return throttler.DefaultThrottler
}

func WithLogger(ctx context.Context, logger log.Logger) context.Context {
	return context.WithValue(ctx, loggerKey, logger)
}

func WithStats(ctx context.Context, client stats.Client) context.Context {
	return context.WithValue(ctx, statsKey, client)
}

func Stats(ctx context.Context) stats.Client {
	if v, ok := ctx.Value(statsKey).(stats.Client); ok {
		return v
	}
	return stats.NullStatter
}

func Logger(ctx context.Context) log.Logger {
	if v, ok := ctx.Value(loggerKey).(log.Logger); ok {
		return v
	}
	return log.NewNullLogger()
}

func WithReporter(ctx context.Context, reporter o11y.ExceptionReporter) context.Context {
	return context.WithValue(ctx, reporterKey, reporter)
}

func Reporter(ctx context.Context) o11y.ExceptionReporter {
	if v, ok := ctx.Value(reporterKey).(o11y.ExceptionReporter); ok {
		return v
	}
	return exceptions.NullReporter
}

func Report(ctx context.Context, err error, payload map[string]string) {
	if reportErr := Reporter(ctx).Report(context.Background(), err, payload); reportErr != nil {
		Logger(ctx).WithError(reportErr).Error("failed to report error", kvp.String("gh.turboscan.error", err.Error()))
	}
}

func ReportSensitive(ctx context.Context, err error, payload, sensitivePayload map[string]string) {
	if reportErr := Reporter(ctx).ReportSensitive(context.Background(), err, payload, sensitivePayload); reportErr != nil {
		Logger(ctx).WithError(reportErr).Error("failed to report sensitive error", kvp.String("gh.turboscan.error", err.Error()))
	}
}

func WithContext(cfg *config.Config, name string, fn func(ctx context.Context) error) error {
	ctx := context.Background()

	logger, err := cfg.NewLogger()
	if err != nil {
		return err
	}

	logger = logger.WithFields(kvp.String("gh.turboscan.app", name), kvp.String("gh.turboscan.env", cfg.Environment))

	stopTracing := o11y.StartTracing(logger)
	defer stopTracing()

	statsClient := cfg.NewStatsClient(name)
	ctx = WithStats(ctx, statsClient)
	statsClient.Run()
	defer statsClient.Stop()

	reporter, err := cfg.ExceptionReporter(logger, name, statsClient)
	if err != nil {
		return err
	}

	ctx = WithReporter(ctx, reporter)

	ctx = WithLogger(ctx, logger)

	statsReporter := ps.Reporter{Stats: statsClient}

	reporterCtx := ctx
	go func() {
		if reporterErr := statsReporter.Run(reporterCtx); reporterErr != nil {
			logger.WithError(reporterErr).Error("error running stats reporter")
		}
	}()

	frenoThrottler := cfg.NewFrenoThrottler()

	ctx = context.WithValue(ctx, throttlerKey, frenoThrottler)

	return fn(ctx)
}
